def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

results = []
matches = []

for k in range(1, 31):
    n = 2 * (k**3)
    tau_n = tau(n)
    two_k = 2 * k

    is_match = (tau_n == two_k)

    results.append((k, n, tau_n, two_k, is_match))

    if is_match:
        matches.append(k)

print("K | 2K^3 | tau(2K^3) | 2K | Match")
print("-" * 40)
for k, n, tau_n, two_k, is_match in results:
