print("\nMatches found for k:", matches)

import math

def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0
    count = 0
    # Iterate up to sqrt(n)
    limit = int(math.sqrt(n))
    for i in range(1, limit + 1):
        if n % i == 0:
            # If i is a divisor, n/i is also a divisor
            if i * i == n:
                count += 1  # Perfect square
            else:
                count += 2  # Pair of divisors
    return count

def is_prime(n):
    """Checks if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Find all odd primes p such that k = 2p <= 100, so p <= 50.
odd_primes = [p for p in range(3, 51) if is_prime(p)]

results = []
for p in odd_primes:
    k = 2 * p

    # Calculate N = 2k^3
    N = 2 * (k**3)

    # Calculate tau(N)
    tau_N = count_divisors(N)

    # Check the condition: tau(2k^3) = 2k
    condition_met = (tau_N == 2 * k)

    results.append({
        'k': k,
        'p': p,
        'N': N,
        'tau_N': tau_N,
        '2k': 2 * k,
        'met': condition_met
    })

print("--- Check Results ---")
for res in results:
    print(f"k={res['k']} (p={res['p']}): tau(2k^3) = {res['tau_N']}, 2k = {res['2k']}. Condition met: {res['met']}")

